  for (const s of [-1, 1]) addCylPart(w10DlMarble, 0.26, 0.20, 0.58, 4, cx + s * 72.6, baseY + 0.29, cz - 10.5);
  addW3GroundedPost(w10DlMarble, 0.24, 0.24, baseY + 1.38, baseY, cx - 47.6, cz - 59.5);
