  // 2.3 Hollow Giếng Cổ Đá Ong Đường Lâm (Hollow Laterite Masonry Ring + Dark Reflective Water Inside + Pulley Rope & Wooden Bucket)
  const wellX = cx + 14;
  const wellZ = cz - 4;
