  const wellOuterShape = new THREE.Shape();
  wellOuterShape.absarc(0, 0, 1.62, 0, Math.PI * 2, false);
  const wellInnerHole = new THREE.Path();
  wellInnerHole.absarc(0, 0, 1.18, 0, Math.PI * 2, true);
