  // --- Wave 10 Macro Visual QC & 1954 Trench Details (3545–3572): Field-Signal Canopy, Ordnance & Victory Benches ---
  const w10DbStone: THREE.BufferGeometry[] = [];
  const w10DbTimber: THREE.BufferGeometry[] = [];
